import {normalizeComputer,parseImport,mergeComputers,withPlanned,filterSoftware,escapeHtml as e,capacity,primaryGpu} from './inventory.mjs';
import {mountStorage,mountSubsystems} from './usage-view.mjs';
import {aiSummary,aiDetails,mountAiPackages} from './ai.mjs';
import {nasSummary} from './nas.mjs';
import {usedStorageBytes,bytes} from './usage.mjs';
const tabDefinitions=pc=>[['overview','總覽',''],['hardware','硬體規格',''],['software','軟體清單',pc.software.length],['storage','儲存空間',''],['subsystems','子系統',''],['system','系統環境','']];
const $=selector=>document.querySelector(selector);
const storeKey='pc-atlas.imports.v1';
let computers=[],imported=[],selected='pc_china',tab='overview',mode='inventory',softwareQuery='',ascending=true,deviceQuery='',storageWarning=false;
const date=iso=>new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso)).replaceAll('/','.');
const stamp=iso=>new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(iso));
const isQnap=pc=>!!pc.nas;
const isLinux=pc=>/linux|ubuntu|debian|fedora|centos|qnap|qts|quts/i.test(pc.os?.name??'');
const osFamily=pc=>isQnap(pc)?'QNAP':isLinux(pc)?'Linux':/windows/i.test(pc.os?.name??'')?'Windows':'OS';
const cpuName=pc=>pc.hardware.cpu.map(x=>x.name.replaceAll('(R)','').replaceAll('(TM)','').replace(/\s+CPU\s+@.+$/,'')).join(' / ')||'未取得';
const gpuName=pc=>primaryGpu(pc)?.name??'未取得';
const diskTotal=pc=>pc.hardware.disks.reduce((sum,x)=>sum+(x.sizeGB??0),0);
const available=()=>withPlanned(computers);
const current=()=>available().find(x=>x.id===selected)??available()[0];
const value=v=>v==null||v===''?'—':v;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function table(rows){return `<table class="info-table"><tbody>${rows.map(([label,v])=>`<tr><td>${e(label)}</td><td>${e(value(v))}</td></tr>`).join('')}</tbody></table>`;}
function section(title,subtitle,body){return `<section><div class="block-heading"><h3>${e(title)}</h3><small>${e(subtitle)}</small></div>${body}</section>`;}
const tower=`<div class="device-illustration" aria-hidden="true"><svg viewBox="0 0 150 178" fill="none"><ellipse cx="76" cy="162" rx="61" ry="9" fill="#0e1614"/><path d="M35 26 96 12 127 30 65 45Z" fill="#52614b" stroke="#81966e"/><path d="M35 26 65 45V158L35 139Z" fill="#2b3730" stroke="#687e58"/><path d="M65 45 127 30V144L65 158Z" fill="#233028" stroke="#81966e"/><path d="M72 51 119 40V135L72 146Z" fill="#14221b" stroke="#4a603f"/><path d="m77 56 36-9v70l-36 8Z" fill="#2a392c"/><g stroke="#7f9c65"><ellipse cx="95" cy="69" rx="12" ry="14" transform="rotate(14 95 69)"/><ellipse cx="95" cy="101" rx="12" ry="14" transform="rotate(14 95 101)"/></g><g stroke="#627b50"><ellipse cx="95" cy="69" rx="7" ry="9"/><ellipse cx="95" cy="101" rx="7" ry="9"/></g><circle cx="95" cy="69" r="3" fill="#b7dc85"/><circle cx="95" cy="101" r="3" fill="#b7dc85"/><path d="m40 42 18 11m-18-5 18 11m-18 49 18 11m-18-5 18 11m-18-5 18 11" stroke="#718366"/><path d="m78 134 34-8" stroke="#718366" stroke-width="3"/><circle cx="119" cy="35" r="1.4" fill="#cefa90"/><path d="M42 144v6m75-2v6" stroke="#657d58" stroke-width="4"/><path d="M20 164h19m91-14h15M20 47h8m105 41h10" stroke="#647857" stroke-dasharray="2 3"/></svg><span class="tower-label">PERSONAL WORKSTATION / 01</span></div>`;
function renderSidebar(){
  const all=available(),q=deviceQuery.toLowerCase().trim();
  const matches=pc=>!q||[pc.id,pc.status==='collected'?cpuName(pc):'',pc.status==='collected'?gpuName(pc):''].some(x=>x.toLowerCase().includes(q));
  const filtered=all.filter(matches);
  $('#machineList').innerHTML=filtered.length?filtered.map(pc=>`<button class="machine ${pc.id===selected&&mode==='inventory'?'selected':''}" data-machine="${e(pc.id)}" aria-pressed="${pc.id===selected&&mode==='inventory'}"><span class="machine-icon">▧</span><span><span class="machine-name">${e(pc.name)}</span><span class="machine-meta">${pc.status==='collected'?'已擷取 · '+e(osFamily(pc)):'等待加入規格'}</span></span><span class="machine-dot ${pc.status==='collected'?'ready':''}"></span></button>`).join(''):'<div class="no-machines">找不到符合的設備</div>';
  $('#machineCount').textContent=`${computers.length} / ${all.length}`;
  $('#readyCount').innerHTML=`${String(computers.length).padStart(2,'0')} <span>/ ${String(all.length).padStart(2,'0')}</span>`;
  $('#inventoryNav b').textContent=String(all.length).padStart(2,'0');
  $('#deviceIndex').textContent=`${String(Math.max(1,all.findIndex(x=>x.id===selected)+1)).padStart(2,'0')} — ${String(all.length).padStart(2,'0')}`;
  $('#inventoryNav').classList.toggle('active',mode==='inventory');$('#compareNav').classList.toggle('active',mode==='compare');
}
function renderStats(){const pc=current();$('#fleetMemory').textContent=pc.status==='collected'?capacity(pc.hardware.memoryGB):'—';$('#softwareCount').textContent=computers.reduce((sum,x)=>sum+x.software.length,0).toLocaleString();const dates=computers.map(x=>x.collectedAt).sort((a,b)=>new Date(b)-new Date(a));$('#lastUpdated').textContent=dates.length?date(dates[0]):'—';}
function render(){renderSidebar();renderStats();$('#crumb').textContent=mode==='compare'?'規格比較':selected;if(mode==='compare'){renderCompare();return;}const pc=current();if(pc.status!=='collected'){renderPending(pc);return;}
  const h=pc.hardware,gpu=primaryGpu(pc);
  $('#deviceView').innerHTML=`<article class="device-card"><div class="device-hero"><div><div class="device-ident">WORKSTATION <span>● 已建立檔案</span></div><h2>${e(pc.name)}</h2><div class="device-subtitle">${e(h.motherboard[0]?.product||h.model)} <span style="color:#627363">/</span> ${e(pc.os.architecture)}</div><div class="device-tags"><span class="tag">${e(pc.os.name.replace('Microsoft ',''))}</span><span class="tag">${e(gpu?.name.replace('NVIDIA GeForce ','')??'GPU 未取得')}</span><span class="tag">${e(capacity(h.memoryGB))} RAM</span></div></div>${tower}<div class="hero-actions"><button class="button" data-export-pc>↓ 匯出規格</button></div></div><div class="tabs" role="tablist" aria-label="規格分類">${tabDefinitions(pc).map(([id,label,count])=>`<button class="tab ${tab===id?'active':''}" role="tab" id="tab-${id}" aria-selected="${tab===id}" aria-controls="tabPanel" tabindex="${tab===id?'0':'-1'}" data-tab="${id}">${label}${count?` <span>${count}</span>`:''}</button>`).join('')}</div><div class="panel-body" id="tabPanel" role="tabpanel" aria-labelledby="tab-${tab}"></div><div class="snapshot-foot"><span><i class="tiny-dot"></i> 擷取完成 · ${e(pc.source)}</span><span>${e(stamp(pc.collectedAt))} (台北) · 靜態快照</span></div></article>`;
  const panel=$('#tabPanel');if(tab==='storage')mountStorage(panel,pc);if(tab==='subsystems')mountSubsystems(panel,pc);if(tab==='overview')panel.innerHTML=overview(pc);if(tab==='hardware')panel.innerHTML=hardware(pc);if(tab==='system'){panel.innerHTML=system(pc);mountAiPackages(panel,pc);}if(tab==='software'){panel.innerHTML=`<div class="software-toolbar"><input id="softwareSearch" type="search" placeholder="搜尋軟體名稱、版本或發行者…" aria-label="搜尋已安裝軟體" value="${e(softwareQuery)}"><span id="softwareResultCount"></span></div><div id="softwareResults" aria-live="polite"></div>`;renderSoftware();}
}
function overview(pc){const h=pc.hardware,cpu=h.cpu[0],gpu=primaryGpu(pc),memorySpeeds=[...new Set(h.memory.map(x=>x.configuredMHz||x.speedMHz).filter(Boolean))].join(' / ');
  const cards=[['PROCESSOR','▧',cpuName(pc).replace('Intel Core ','').replace('AMD Ryzen ','Ryzen '),cpu?`${cpu.cores??'—'} 核心 / ${cpu.threads??'—'} 執行緒`:'未取得 CPU 資料'],['MEMORY','▥',capacity(h.memoryGB),h.memory.length?`${h.memory.length} 個模組${memorySpeeds?` · ${memorySpeeds} ${h.memory[0]?.speedUnit||'MHz'}`:''}`:h.memorySource==='os-visible'?'OS 可見容量 · 模組資料未取得':'記憶體模組資料未取得'],['GRAPHICS','◈',gpuName(pc).replace('NVIDIA GeForce ',''),gpu?.vramMB?`${gpu.vramMB/1024} GB VRAM · NVIDIA`:'顯示記憶體未取得'],['STORAGE','▤',h.disks.length?capacity(diskTotal(pc)):'—',pc.nas?`${h.disks.filter(x=>x.mediaType!=='eMMC').length} 顆資料硬碟 · 另含 eMMC`:`${h.disks.length} 顆實體磁碟 · 二進位容量`]];
  return `<div class="hardware-grid">${cards.map(([label,icon,v,note])=>`<div class="spec-card"><small>${label}</small><span class="spec-symbol">${icon}</span><strong>${e(v)}</strong><p>${e(note)}</p></div>`).join('')}</div>${aiSummary(pc)}${nasSummary(pc)}<div class="details-grid">${section('系統與主機板','SYSTEM INFO',table([['作業系統',pc.os.name],['系統版本',`${pc.os.version} · Build ${pc.os.build}`],['主機板',h.motherboard[0]?.product],['BIOS 版本',`${h.bios.manufacturer} ${h.bios.version}`],['顯示驅動',gpu?.driver]]))}${section('磁碟使用狀況','VOLUME USAGE',volumes(h.volumes.slice(0,4)))}</div>${pc.warnings.length?`<div class="info-note">${pc.warnings.map(e).join('<br>')}</div>`:''}`;
}
function volumes(items){return items.length?items.map(v=>{const used=v.sizeGB?Math.max(0,Math.min(100,100*(v.sizeGB-(v.freeGB??0))/v.sizeGB)):0;return `<div class="storage-row"><div class="storage-label"><span class="mono">${e(v.drive)} <span style="color:#7d9281">${e(v.fileSystem)}</span></span><span>${e(capacity(v.freeGB))} 可用 / ${e(capacity(v.sizeGB))}</span></div><div class="storage-track" role="meter" aria-label="${e(v.drive)} 已使用百分比" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(used)}"><i style="width:${used}%"></i></div></div>`;}).join(''):'<p class="compare-note">未取得磁碟區資料</p>';}
function hardware(pc){const h=pc.hardware;return `<div class="details-grid">${section('處理器','CPU',h.cpu.map(x=>table([['型號',x.name],['核心 / 執行緒',`${x.cores??'—'} / ${x.threads??'—'}`],['最高時脈',x.maxClockMHz?`${x.maxClockMHz} MHz`:'—']])).join('')||'未取得')}${section('主機板與 BIOS','MAINBOARD',table([['製造商',h.motherboard[0]?.manufacturer],['主機板',h.motherboard[0]?.product],['板本版本',h.motherboard[0]?.version],['BIOS',`${h.bios.manufacturer} ${h.bios.version}`]]))}</div>${section(`記憶體模組 · ${capacity(h.memoryGB)}`,'MEMORY',`<div class="table-scroll"><table class="software-table"><thead><tr><th>插槽 / 型號</th><th>容量</th><th>設定時脈</th></tr></thead><tbody>${h.memory.length?h.memory.map(x=>`<tr><td><span class="mono">${e(x.slot)}</span><br>${e(x.manufacturer)} ${e(x.partNumber)}</td><td>${e(capacity(x.capacityGB))}</td><td>${e(x.configuredMHz||x.speedMHz||'—')} ${e(x.speedUnit||'MHz')}</td></tr>`).join(''):'<tr><td colspan="3">未取得 DIMM 模組明細；目前記憶體容量為 OS 可見容量。</td></tr>'}</tbody></table></div>`)}${section('顯示卡與顯示介面','GRAPHICS',h.gpu.map(x=>table([['裝置',x.name+(x.virtual?'（虛擬 / 遠端）':'')],['顯示記憶體',x.vramMB?`${x.vramMB/1024} GB`:'未取得'],['驅動版本',x.driver]])).join(''))}${section(`實體磁碟 · ${h.disks.length} 顆`,'PHYSICAL DISKS',table(h.disks.map((x,i)=>[`磁碟 ${i+1}`,`${x.name} · ${capacity(x.sizeGB)} · ${x.interface}`])))}${section('所有磁碟區','ALL VOLUMES',volumes(h.volumes))}${section('網路介面','NETWORK',table(h.network.map(x=>[x.connected?'已連線':'未連線',`${x.name}${x.speedMbps?` · ${x.speedMbps} Mbps`:''}`])))}<p class="compare-note">容量以 GiB / TiB 換算（畫面簡記為 GB / TB）。實體磁碟與磁碟區分別列示；磁碟區可能包含虛擬裝置。</p>`;}
function system(pc){return `${aiDetails(pc)}<div class="details-grid">${section('作業系統','OPERATING SYSTEM',table([['名稱',pc.os.name],['版本',pc.os.version],['Build',pc.os.build],['架構',pc.os.architecture]]))}${section('開發工具','DEVELOPER TOOLS',pc.tools.length?table(pc.tools.map(x=>[x.name,x.version])):'<p class="compare-note">未偵測到可直接執行的開發工具</p>')}</div>${section('資料來源','ABOUT THIS SNAPSHOT',table([['設備名稱',pc.id],['擷取時間',`${stamp(pc.collectedAt)} (Asia/Taipei)`],['來源',pc.source],['軟體範圍',isQnap(pc)?'QNAP QPKG / App Center 已安裝項目；Python 套件見 AI 環境':isLinux(pc)?'dpkg 已安裝套件；不包含所有可攜式程式或語言套件':'Windows 登錄檔中可讀取的已安裝程式；不包含所有可攜式程式或套件'],['工具版本','工具為 PATH 偵測結果；不代表所有已安裝環境'],['隱私','不擷取序號、IP、MAC、帳號或授權金鑰']]))}`;}
function renderSoftware(){const pc=current(),items=filterSoftware(pc.software,softwareQuery,ascending);$('#softwareResultCount').textContent=`${items.length} / ${pc.software.length} 筆軟體`;
  $('#softwareResults').innerHTML=items.length?`<table class="software-table"><thead><tr><th><button data-sort-name aria-label="切換軟體名稱排序">軟體名稱 ${ascending?'↑':'↓'}</button></th><th>版本</th><th>發行者</th></tr></thead><tbody>${items.map(x=>`<tr><td>${e(x.name)}</td><td>${e(value(x.version))}</td><td>${e(value(x.publisher))}</td></tr>`).join('')}</tbody></table>`:'<div class="results-empty">找不到符合的軟體，請試試其他關鍵字。</div>';
}
function renderPending(pc){$('#deviceView').innerHTML=`<div class="device-card pending-view"><div><span class="tag">尚未匯入</span><div class="pending-symbol">▧</div><h2>${e(pc.name)}</h2><p>這台電腦的檔案已預留。執行規格擷取工具，匯入 JSON 後，就能在這裡瀏覽它的完整配置。</p><button class="button primary" data-open-help>＋ 加入 ${e(pc.name)} 的規格</button></div></div>`;}
function renderCompare(){const all=available();const rows=[['工作用途',pc=>pc.workPurpose??''],['資料狀態',pc=>'已擷取'],['處理器',cpuName],['核心 / 執行緒',pc=>pc.hardware.cpu.map(x=>`${x.cores??'—'} / ${x.threads??'—'}`).join(', ')],['記憶體',pc=>capacity(pc.hardware.memoryGB)],['顯示卡',gpuName],['顯示記憶體',pc=>primaryGpu(pc)?.vramMB?`${primaryGpu(pc).vramMB/1024} GB`:'未取得'],['實體儲存',pc=>capacity(diskTotal(pc))],['已用儲存',pc=>bytes(usedStorageBytes(pc))],['作業系統',pc=>pc.os.name],['已安裝軟體',pc=>`${pc.software.length} 筆`],['擷取日期',pc=>date(pc.collectedAt)]];
  $('#deviceView').innerHTML=`<article class="device-card"><div class="panel-body"><div class="block-heading"><h3>設備規格比較</h3><small>${computers.length} COLLECTED / ${all.length} MACHINES</small></div><p class="compare-note">將各台電腦的主要配置並排檢視。已用儲存依最新快照中的實體磁碟區計算，與原始硬碟容量分開列示。</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>規格項目</th>${all.map(pc=>`<th>${e(pc.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,get])=>`<tr><td>${e(label)}</td>${all.map(pc=>`<td>${pc.status==='collected'||label==='工作用途'?e(get(pc)):'<span style="color:#6b7e70">待匯入</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div></article>`;
}
function selectMachine(id){selected=id;mode='inventory';softwareQuery='';history.replaceState(null,'',`#${id}`);render();}
document.addEventListener('click',event=>{const t=event.target.closest('button');if(!t)return;if(t.dataset.machine)selectMachine(t.dataset.machine);if(t.dataset.tab){tab=t.dataset.tab;render();$(`#tab-${tab}`).focus();}if(t.hasAttribute('data-sort-name')){ascending=!ascending;renderSoftware();$('#softwareResults [data-sort-name]').focus();}if(t.hasAttribute('data-export-pc'))download(`${selected}.json`,current());if(t.hasAttribute('data-open-help'))$('#helpDialog').showModal();});
$('#deviceView').addEventListener('keydown',event=>{if(!event.target.matches('[role="tab"]'))return;const tabs=[...document.querySelectorAll('[role="tab"]')];const index=tabs.indexOf(event.target);let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();tab=tabs[next].dataset.tab;render();$(`#tab-${tab}`).focus();}});
document.addEventListener('input',event=>{if(event.target.id==='softwareSearch'){softwareQuery=event.target.value;renderSoftware();}if(event.target.id==='deviceSearch'){deviceQuery=event.target.value;renderSidebar();}});
$('#inventoryNav').onclick=()=>{mode='inventory';render();};$('#compareNav').onclick=()=>{mode='compare';render();};
$('#addMachine').onclick=()=>$('#importFile').click();$('#helpButton').onclick=()=>$('#helpDialog').showModal();$('#closeHelp').onclick=()=>$('#helpDialog').close();$('#importFromHelp').onclick=()=>{$('#helpDialog').close();$('#importFile').click();};
$('#exportAll').onclick=()=>download('pc-atlas-inventory.json',{schemaVersion:1,exportedAt:new Date().toISOString(),computers});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!event.ctrlKey&&!event.metaKey&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#helpDialog').open){event.preventDefault();$('#deviceSearch').focus();}});
$('#importFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('檔案不可超過 10 MB');const incoming=parseImport(JSON.parse((await file.text()).replace(/^\uFEFF/,'')));const merged=mergeComputers(computers,incoming),nextImported=mergeComputers(imported,incoming);try{localStorage.setItem(storeKey,JSON.stringify(nextImported));}catch{throw new Error('瀏覽器儲存空間不足或不可用，無法保存匯入資料');}imported=nextImported;computers=merged;selectMachine(incoming[0].id);toast(`已匯入 ${incoming.length} 台電腦，並儲存至此瀏覽器`);}catch(error){toast(`匯入失敗：${error.message}`);}finally{event.target.value='';}};
async function init(){try{const response=await fetch('data/index.json');if(!response.ok)throw new Error('無法讀取規格資料目錄');const files=await response.json();if(!Array.isArray(files)||!files.length||files.some(x=>typeof x!=='string'||!/^[a-zA-Z0-9_-]+\.json$/.test(x)))throw new Error('規格資料目錄格式錯誤');computers=await Promise.all(files.map(async file=>{const r=await fetch(`data/${file}`);if(!r.ok)throw new Error(`無法讀取 ${file}`);return normalizeComputer(await r.json());}));try{const saved=localStorage.getItem(storeKey);if(saved){imported=parseImport(JSON.parse(saved));computers=mergeComputers(computers,imported.map(pc=>{const base=computers.find(x=>x.id===pc.id);return base&&Date.parse(pc.collectedAt)<Date.parse(base.collectedAt)?{...base,workPurpose:pc.workPurpose??base.workPurpose,storageSnapshots:pc.storageSnapshots,subsystems:pc.subsystems,ai:pc.ai}:pc;}));}}catch{storageWarning=true;}const hash=location.hash.slice(1);if(available().some(x=>x.id===hash))selected=hash;render();if(storageWarning)toast('瀏覽器的既存資料無法讀取，已載入網站內建規格。');}catch(error){$('#deviceView').innerHTML=`<div class="error-box">${e(error.message)}。請透過網頁伺服器開啟此網站並重新載入。</div>`;}}
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(available().some(x=>x.id===hash))selectMachine(hash);});
init();

// Usage collection runs on the selected PC; a static browser cannot query its disks or Docker daemon.
document.addEventListener('click',event=>{
  const button=event.target.closest('button');if(!button)return;
  if(button.dataset.usageHelp){
    const kind=button.dataset.usageHelp,pc=current();
    $('#usageHelpTitle').textContent=kind==='storage'?'擷取儲存空間快照':'更新子系統盤點';
    $('#usageCommand').textContent=isQnap(pc)?`python collect-ssh.py --host pc_nas --platform qnap --name ${pc.id} --output ${pc.id}.json`:isLinux(pc)?`python collect-ssh.py --host ${pc.id} --name ${pc.id} --output ${pc.id}.json`:`python collect-usage.py --computer ${pc.id}.json --kind ${kind}`;
    $('#usageHelpDownloads').innerHTML=isQnap(pc)?'<a href="collect-ssh.py" download>下載 collect-ssh.py ↓</a>，以及 <a href="scripts/collect-qnap.py" download>scripts/collect-qnap.py ↓</a>、<a href="scripts/ai-probe.py" download>scripts/ai-probe.py ↓</a>（保留 scripts 子資料夾）。在已設定 pc_nas SSH 別名的管理電腦執行。':isLinux(pc)?'<a href="collect-ssh.py" download>下載 collect-ssh.py ↓</a>，以及 <a href="scripts/collect-linux.py" download>scripts/collect-linux.py ↓</a> + <a href="scripts/ai-probe.py" download>scripts/ai-probe.py</a>（保留 scripts 子資料夾）。在已設定 SSH 金鑰的管理電腦執行。':'<a href="collect-usage.py" download>下載 collect-usage.py ↓</a>，再 <button class="text-button" data-usage-download-pc>下載目前電腦的規格 JSON ↓</button>，放在同一資料夾。';
    $('#usageHelpDialog').showModal();
  }
  if(button.dataset.usageExport){
    const pc=current(),storage=button.dataset.usageExport==='storage';
    // Export a complete PC record so this file can be imported through the existing flow.
    download(`${pc.id}-${storage?'storage':'subsystems'}.json`,pc);
  }
});
$('#closeUsageHelp').onclick=()=>$('#usageHelpDialog').close();
document.addEventListener('click',event=>{if(event.target.closest('[data-usage-download-pc],#usageDownloadPc'))download(`${current().id}.json`,current());});
$('#usageImport').onclick=()=>{$('#usageHelpDialog').close();$('#importFile').click();};
